document.querySelectorAll('#customerTabs [data-bs-toggle="tab"]').forEach(button=>button.addEventListener('shown.bs.tab',event=>{const url=new URL(window.location.href);if(event.target.dataset.bsTarget==='#appointments-pane')url.searchParams.set('tab','appointments');else url.searchParams.delete('tab');window.history.replaceState({},'',url);}));
const appointmentForm=document.getElementById('customerAppointmentForm');
const startTime=document.getElementById('preferred_start_time');
const endTime=document.getElementById('preferred_end_time');
function validateAppointmentTime(){if(!startTime||!endTime)return;endTime.setCustomValidity(endTime.value&&startTime.value&&endTime.value<=startTime.value?'The end time must be after the start time.':'');}
startTime?.addEventListener('input',validateAppointmentTime);endTime?.addEventListener('input',validateAppointmentTime);appointmentForm?.addEventListener('submit',validateAppointmentTime);
</script>@endif
